---@param goodsId integer @ 消耗道具id
---@param consumeNum integer @ 消耗数量
---@param isNotChangeColor boolean | nil @ 是否不需要 道具不足时数量变色（默认变）
---@param defaultMode integer | nil @ 1白，2黑（默认1）
---@param extraParams table | nil
function CommonBtnConsumePop:RefreshUI(goodsId, consumeNum, isNotChangeColor, defaultMode, extraParams)
    if checkNumber(goodsId) == 0 then
        return
    end
    defaultMode = defaultMode or 1
    
    consumeNum = checkNumber(consumeNum)
    ---@type GoodsVo
    local goodsVo = goodsConfMgr:GetGoodsVoById(goodsId)
    if isNull(goodsVo) then
        printInfo("id %s 找不到道具信息",goodsId)
    end
    if goodsVo and self.goodsId ~= goodsId then
        self.goodsId = goodsId
        self.Icon:LoadSprite(goodsVo.photoPath)
    end

    local curNum = GoodsUtils.GetThingNo(goodsId)
    if checkNumber(goodsId) == ActionUtils.GetDailyQuestTicketId() then
        curNum = ActionUtils.GetDailyQuestCurTicketAddNum()
    end

    self:SetBackgroundColor(defaultMode)
    self.ConsumeNum.textComp.text = string.format("x%s", consumeNum)
    if not isNotChangeColor then
        self.ConsumeNum.Status = curNum >= consumeNum and defaultMode or 3
    end
    if extraParams then
        if checkNumber(extraParams.goodsId) == 0 then
            CfUtils.SetActive(self.Icon2, false)
            CfUtils.SetActive(self.ConsumeNum2, false)
            if checkNumber(extraParams.questId) > 0 then
                local vo = QuestConfMgr:GetInstance():GetQuestVoById(extraParams.questId)
                if not vo then
                    return
                end
                if checkNumber(vo.levelType) == Constants.RegionSecondQuestType.Equip then
                    ---装备本
                    --@type PlayerComponent
                    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
                    local status = checkNumber(playerComponent.playerDojo.consumeCopyActivity.status)
                    local times = checkNumber(playerComponent.playerDojo.consumeCopyActivity.residueNum)
                    CfUtils.SetActive(self.controller.transform:Find("TextOriginal"), status == 1 and times > 0)
                    if status == 1 and times > 0  then
                        CfUtils.SetActive(self.controller.transform:Find("TextOriginal/ImgLine"), true)
                        ---@type TableML.TableFile
                        local tableFile = settingModule.Get(AutoIds.IdSetting313)
                        ---@type TableML.TableFileRow
                        local row = tableFile:GetByPrimaryKey(checkNumber(extraParams.questId), false)
                        if row then
                            local costNum = checkNumber(row:Get("costNum")) + checkNumber(vo.costNumLose)
                            CfUtils.FillText(self.controller.transform:Find("TextOriginal"),  "x" .. checkNumber(vo.costNum) + checkNumber(vo.costNumLose))
                            CfUtils.FillText(self.controller.transform:Find("Text2"), "x" .. checkNumber(costNum))
                            if not isNotChangeColor then
                                self.ConsumeNum.Status = curNum >= costNum and defaultMode or 3
                            end
                        end
                    end
                else
                    CfUtils.SetActive(self.controller.transform:Find("TextOriginal"), false)
                end
            end
            return
        end
        CfUtils.SetActive(self.Icon2, true)
        CfUtils.SetActive(self.ConsumeNum2, true)

        local exCurNum = GoodsUtils.GetThingNo(extraParams.goodsId)
        local exConsumeNum = checkNumber(extraParams.consumeNum)
        ---@type GoodsVo
        local exGoodsVo = goodsConfMgr:GetGoodsVoById(extraParams.goodsId)
        self.Icon2:LoadSprite(exGoodsVo.photoPath)
        self.ConsumeNum2.textComp.text = string.format("x%s", exConsumeNum)
        if not isNotChangeColor then
            self.ConsumeNum2.Status = exCurNum >= exConsumeNum and defaultMode or 3
        end
    else
        CfUtils.SetActive(self.Icon2, false)
        CfUtils.SetActive(self.ConsumeNum2, false)
    end
end

---@param consumeList {goodsId:number, num?:number, consumeNum?:number, goodsNum?:number}[]
---@param isNotChangeColor? boolean
---@param defaultMode? number
function CommonBtnConsumePop:RefreshUIByConsumeList(consumeList, isNotChangeColor, defaultMode)
    defaultMode = defaultMode or 1

    self:SetBackgroundColor(defaultMode)

    local componentList = self._componentList
    local forTimes = math.max(#consumeList, #componentList)

    for i = 1, forTimes, 1 do
        local components = componentList[i]
        local iconComp, textComp
        if components == nil then
            local parent = self.CommonBtnConsumePop.gameObject

            local icon = parent:AddChild(self.Icon.gameObject)
            iconComp = icon:GetComponent(ImageAlterableType)
            icon.transform.localScale = self.Icon.transform.localScale

            local numGo = parent:AddChild(self.ConsumeNum.gameObject)
            textComp = numGo:GetComponent(UISwitchTextMeshProType)

            componentList[i] = {iconComp, textComp}

        else
            iconComp, textComp = SafeUnpack(components)

        end

        local consumeData = consumeList[i]
        local isShow = consumeData ~= nil
        SetActive(iconComp, isShow)
        SetActive(textComp, isShow)

        if isShow then
            self:RefreshIcon(iconComp, consumeData)
            self:RefreshNum(textComp, consumeData, isNotChangeColor, defaultMode)
        end
    end

end

---@param iconComp Engine.UI.ImageAlterable
---@param consumeData {goodsId:number, num?:number, consumeNum?:number, goodsNum?:number}
function CommonBtnConsumePop:RefreshIcon(iconComp, consumeData)
    ---@type GoodsVo
    local goodsVo = goodsConfMgr:GetGoodsVoById(consumeData.goodsId)
    iconComp:LoadSprite(goodsVo.photoPath)
end


---@param textComp Game.Native.Common.UISwitchTextMeshPro
---@param consumeData {goodsId:number, num?:number, consumeNum?:number, goodsNum?:number}
---@param isNotChangeColor? boolean
---@param defaultMode number
function CommonBtnConsumePop:RefreshNum(textComp, consumeData, isNotChangeColor, defaultMode)
    local num = GoodsUtils.GetThingNo(consumeData.goodsId)

    local consumeNum = consumeData.num or consumeData.consumeNum or consumeData.goodsNum

    textComp.textComp.text = string.format("x%s", consumeNum)
    if not isNotChangeColor then
        textComp.Status = num >= consumeNum and defaultMode or 3
    end
end

--- SetBackgroundColor
---@param status number @ 1:white 2:black
function CommonBtnConsumePop:SetBackgroundColor(status)
    status = status or 1
    CfUtils.SetUISwitchImage(self.controller.gameObject, status)
end

